goal.statement:
let natToInt := fun u j => ↑(u j);
let natToReal := fun u j => ↑(u j);
let intToReal := fun u j => ↑(u j);
let C := {x | ∃ c, (∀ (i : Fin d), 0 ≤ c i) ∧ x = ∑ i, c i • fun j => ↑(a i j)};
let relintC := {x | ∃ c, (∀ (i : Fin d), 0 < c i) ∧ x = ∑ i, c i • fun j => ↑(a i j)};
let fundamentalParallelepiped := {x | ∃ c, (∀ (i : Fin d), 0 ≤ c i ∧ c i < 1) ∧ x = ∑ i, c i • fun j => ↑(a i j)};
let apery := {w | w ∈ S ∧ ∀ (i : Fin d), ¬∃ s ∈ S, w = s + a i};
let leS := fun u v => ∃ s ∈ S, v = u + s;
let maximalApery := fun m => m ∈ apery ∧ ∀ w ∈ apery, leS m w → leS w m;
let QF := {f | ∃ m, maximalApery m ∧ f = natToInt m - ∑ i, natToInt (a i)};
let G := {z | ∃ u ∈ S, ∃ v ∈ S, z = natToInt u - natToInt v};
let normal := natToInt '' ↑S = G ∩ {z | intToReal z ∈ C};
let condition2 := ∀ f ∈ QF, -f ∈ natToInt '' ↑S ∧ intToReal (-f) ∈ relintC;
let condition3 := ∀ f ∈ QF, intToReal (-f) ∈ relintC;
let condition4 := ∀ w ∈ apery, natToReal w ∈ fundamentalParallelepiped;
(normal ↔ condition2) ∧ (normal ↔ condition3) ∧ (normal ↔ condition4)

